// An object of another class, or one that is no instance at all, arrives where the type says Dog. The type checker accepts every line under `strict`: there is no `any`, no cast, no user type guard and no declaration without a body.
// Each way for the value to arrive is crossed with the places where it goes next. A compiled program prints what plain Bun prints, or throws a TypeError where a rule of the compiler says so. It never reads a value as something that it is not.
function t(name: string, f: () => unknown) { let r: string; try { r = String(f()); } catch (e) { r = "threw " + (e instanceof Error ? e.name : typeof e); } console.log(name, r); }
class Animal { name = "animal"; }
class Dog extends Animal { legs = 4; bark(): number { return this.legs * 2; } }
class Cat extends Animal { lives = "nine"; }
t("a wider alias stores into a property of a literal: a typed field", () => { const kennel = { pet: new Dog() }; const home: { pet: Animal } = kennel; home.pet = new Cat(); const bad = kennel.pet; class Pen { pet: Dog = new Dog(); legs(): number { return this.pet.legs + 1; } } const pen = new Pen(); pen.pet = bad; return pen.legs(); });
